bitflags :: bitflags ! { impl AdtFlags : u16 { const NO_ADT_FLAGS = 0 ; # [doc = " Indicates whether the ADT is an enum."] const IS_ENUM = 1 << 0 ; # [doc = " Indicates whether the ADT is a union."] const IS_UNION = 1 << 1 ; # [doc = " Indicates whether the ADT is a struct."] const IS_STRUCT = 1 << 2 ; # [doc = " Indicates whether the ADT is a struct and has a constructor."] const HAS_CTOR = 1 << 3 ; # [doc = " Indicates whether the type is `PhantomData`."] const IS_PHANTOM_DATA = 1 << 4 ; # [doc = " Indicates whether the type has a `#[fundamental]` attribute."] const IS_FUNDAMENTAL = 1 << 5 ; # [doc = " Indicates whether the type is `Box`."] const IS_BOX = 1 << 6 ; # [doc = " Indicates whether the type is `ManuallyDrop`."] const IS_MANUALLY_DROP = 1 << 7 ; # [doc = " Indicates whether the variant list of this ADT is `#[non_exhaustive]`."] # [doc = " (i.e., this flag is never set unless this ADT is an enum)."] const IS_VARIANT_LIST_NON_EXHAUSTIVE = 1 << 8 ; # [doc = " Indicates whether the type is `UnsafeCell`."] const IS_UNSAFE_CELL = 1 << 9 ; # [doc = " Indicates whether the type is `UnsafePinned`."] const IS_UNSAFE_PINNED = 1 << 10 ; # [doc = " Indicates whether the type is `Pin`."] const IS_PIN = 1 << 11 ; # [doc = " Indicates whether the type is `#[pin_project]`."] const IS_PIN_PROJECT = 1 << 12 ; } }